<?php require_once 'php/db.php'; header('Content-Type: text/plain');$stmt = $db->query("SHOW TABLES"); $tables = $stmt->fetchAll(PDO::FETCH_COLUMN); foreach ($tables as $t) { echo "=== TABLE: $t ===\\n"; $stmt2 = $db->query("DESCRIBE `$t`"); $fields = $stmt2->fetchAll(PDO::FETCH_ASSOC); foreach ($fields as $f) { echo sprintf("  %-20s %-15s %-5s %-3s %-10s %s\\n", $f['Field'], $f['Type'], $f['Null'], $f['Key'], $f['Default'] ?? 'NULL', $f['Extra']); } echo "\\n"; }
